public TFMDocumentDeviceId parmdeviceID(TFMDocumentDeviceId _deviceId)
{
    TFMDocumentDeviceId deviceId = next parmdeviceID(_deviceId);
    TFMDeviceTable		devices = TFMDeviceTable::FindOrCreateDevice(deviceId);

    if (!location)
    {
        location = MobInventLocationsGroupRights::getDefaultWarehouse().InventLocationId;
    }

    return deviceId;
}
